using System.Diagnostics;
using System.Text;

using Microsoft.Extensions.DependencyInjection;

using Paduraksa.Admin.OpenApi;
using Paduraksa.Server.Hosting;

namespace Paduraksa.Tests.Integration.Admin;

/// <summary>
/// The API description is generated by ASP.NET from the endpoints, which takes seconds of CPU and gigabytes of allocation, so the server ships a copy
/// (<c>src/Paduraksa.Admin/OpenApi/openapi.v1.json</c>, embedded) instead of generating it on the first request of every boot. These tests keep the copy equal to
/// what the endpoints generate, and keep the first request from generating anything.
/// </summary>
public sealed class OpenApiSnapshotTests
{
    private const string UpdateVariable = "PADURAKSA_UPDATE_OPENAPI";

    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    [Fact]
    public async Task TheShippedDocumentIsWhatTheEndpointsGenerate()
    {
        await using var h = await AdminHarness.StartAsync();
        var generated = await OpenApiDocumentCache.GenerateAsync(h.Host.GetServices(HostRole.Admin));
        var path = ShippedDocumentPath();

        if (Environment.GetEnvironmentVariable(UpdateVariable) == "1")
        {
            await File.WriteAllBytesAsync(path, generated, Ct);
            return;
        }

        var shipped = await File.ReadAllBytesAsync(path, Ct);
        Assert.True(
            generated.AsSpan().SequenceEqual(shipped),
            $"The API changed and the shipped description did not follow: {FirstDifference(Encoding.UTF8.GetString(shipped), Encoding.UTF8.GetString(generated))}\n"
            + $"Regenerate it and commit the result: {UpdateVariable}=1 dotnet test --project tests/Paduraksa.Tests.Integration --filter-class \"*OpenApiSnapshotTests\"");
        Assert.Equal(shipped, AdminOpenApi.ShippedDocument());
    }

    [Fact]
    public async Task TheFirstRequestServesTheShippedDocumentWithoutGeneratingAnything()
    {
        await using var h = await AdminHarness.StartAsync();
        var cache = h.Host.GetServices(HostRole.Admin).GetRequiredService<OpenApiDocumentCache>();
        Assert.True(cache.ServesShippedDocument);

        // Generating takes seconds even on a quiet machine, so a request that still did it is caught by a bound this loose.
        var clock = Stopwatch.StartNew();
        using var response = await h.GetAsync("/api/v1/openapi.json");
        clock.Stop();

        Assert.Equal(System.Net.HttpStatusCode.OK, response.Status);
        Assert.Equal(AdminOpenApi.ShippedDocument(), Encoding.UTF8.GetBytes(response.Body));
        Assert.True(clock.Elapsed < TimeSpan.FromSeconds(5), $"The first request for the API description took {clock.Elapsed.TotalSeconds:F1} s.");
    }

    private static string FirstDifference(string shipped, string generated)
    {
        var shippedLines = shipped.Split('\n');
        var generatedLines = generated.Split('\n');
        for (var i = 0; i < Math.Min(shippedLines.Length, generatedLines.Length); i++)
        {
            if (!string.Equals(shippedLines[i], generatedLines[i], StringComparison.Ordinal))
            {
                return $"line {i + 1} is\n  {shippedLines[i].Trim()}\nand generates as\n  {generatedLines[i].Trim()}";
            }
        }

        return $"it has {shippedLines.Length} lines and the generated one {generatedLines.Length}";
    }

    private static string ShippedDocumentPath()
    {
        for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
        {
            if (File.Exists(Path.Combine(directory.FullName, "Paduraksa.slnx")))
            {
                return Path.Combine(directory.FullName, "src", "Paduraksa.Admin", "OpenApi", "openapi.v1.json");
            }
        }

        throw new InvalidOperationException("The repository root (Paduraksa.slnx) is not above the test's directory.");
    }
}
